type SurfaceId = `M${string}`
type Props = { onDepthChange?: (deep: boolean) => void; onNavigateRoot?: (root: string) => void }
type Context = { clientId?: string; serviceId?: string; courseId?: string; accountId?: string; alertId?: string }
type Memory = { surface: SurfaceId; stack: SurfaceId[]; clientId: string; serviceId: string; courseId: string; accountId: string; alertId: string }
let navigationMemory: Memory | null = null

const TITLES: Record<SurfaceId, string> = {
  M01:"Más",M02:"Clientes",M03:"Buscar y filtrar",M04:"Ficha de cliente",M05:"Registrar cliente",M06:"Editar datos",M07:"Posibles duplicados",M08:"Fusionar clientes",M09:"Turnos y atenciones",M10:"Compras, pedidos y cobros",M11:"Notas y preferencias",M12:"Contacto y consentimiento",M13:"Archivo y privacidad",M14:"Historial de identidad",
  M15:"Servicios",M16:"Detalle del servicio",M17:"Crear o editar servicio",M18:"Variantes, precio y duración",M19:"Profesionales habilitados",M20:"Disponibilidad pública",M21:"Categorías",M22:"Servicios similares",M23:"Impacto del cambio",M24:"Estado del servicio",M25:"Historia y uso",
  M26:"Cursos",M27:"Detalle del curso",M28:"Crear o editar curso",M29:"Programa y contenidos",M30:"Sesiones",M31:"Nueva sesión",M32:"Reprogramar sesión",M33:"Instructor y recursos",M34:"Inscripciones",M35:"Inscribir participante",M36:"Detalle de inscripción",M37:"Capacidad y espera",M38:"Asistencia",M39:"Finalización y progreso",M40:"Cancelar curso o sesión",M41:"Situación económica",M42:"Cursos históricos",
  M43:"Presencia y promociones",M44:"Información pública",M45:"Galería pública",M46:"Vista previa Cliente",M47:"Revisar y publicar",M48:"Promociones",M49:"Crear promoción",M50:"Objetivos de la promoción",M51:"Vigencia y condiciones",M52:"Vista previa de promoción",M53:"Pausar o finalizar",M54:"Historial de promoción",
  M55:"Horarios y reservas",M56:"Horario local semanal",M57:"Feriados y excepciones",M58:"Reglas generales",M59:"Cancelación, ausencia y seña",M60:"Ventana de anticipación",M61:"Vista previa de disponibilidad",M62:"Conflictos de recursos",M63:"Impacto en reservas",M64:"Recordatorios y confirmaciones",M65:"Historial de disponibilidad",
  M66:"Configuración y acceso",M67:"Datos internos",M68:"Cuentas",M69:"Detalle de cuenta",M70:"Vincular cuenta demo",M71:"Capacidades",M72:"Revisar permisos",M73:"Suspender o reactivar",M74:"Preferencias operativas",M75:"Seguridad y límites demo",
  M76:"Actividad",M77:"Detalle del evento",M78:"Buscar y filtrar actividad",M79:"Avisos",M80:"Detalle del aviso",M81:"Preferencias de avisos",M82:"Recuperación y corrección",M83:"Incidencias cruzadas",
}

const ROOT_ROWS = [
  { id:"M02", label:"Clientes", hint:"Identidades, historial y relaciones", icon:<Users size={21}/> },
  { id:"M15", label:"Servicios", hint:"Catálogo, precios y disponibilidad", icon:<Store size={21}/> },
  { id:"M26", label:"Cursos", hint:"Programa, sesiones e inscripciones", icon:<GraduationCap size={21}/> },
  { id:"M43", label:"Presencia y promociones", hint:"Perfil público demo y campañas", icon:<Megaphone size={21}/> },
  { id:"M55", label:"Horarios y reservas", hint:"Semana, excepciones y reglas", icon:<CalendarDays size={21}/> },
  { id:"M66", label:"Configuración y acceso", hint:"Negocio, cuentas y capacidades", icon:<Settings2 size={21}/> },
  { id:"M76", label:"Actividad y avisos", hint:"Auditoría, alertas e incidencias", icon:<Bell size={21}/> },
] as const

export function MoreSurface({ onDepthChange, onNavigateRoot }: Props) {
  const state = useSyncExternalStore(moreStore.subscribe, moreStore.getSnapshot)
  const query = new URLSearchParams(window.location.search)
  const requestedSurface = query.get("p5Surface")?.toUpperCase() as SurfaceId|undefined
  const initialSurface = requestedSurface&&TITLES[requestedSurface]?requestedSurface:navigationMemory?.surface??"M01"
  const [surface,setSurface] = useState<SurfaceId>(initialSurface)
  const [stack,setStack] = useState<SurfaceId[]>(()=>requestedSurface&&requestedSurface!=="M01"?["M01"]:navigationMemory?.stack??[])
  const [clientId,setClientId] = useState(()=>query.get("clientId")??navigationMemory?.clientId??"CL01")
  const [serviceId,setServiceId] = useState(()=>query.get("serviceId")??navigationMemory?.serviceId??"SV01")
  const [courseId,setCourseId] = useState(()=>query.get("courseId")??navigationMemory?.courseId??"CRS-01")
  const [accountId,setAccountId] = useState(()=>query.get("accountId")??navigationMemory?.accountId??"ACC-OWNER")
  const [alertId,setAlertId] = useState(()=>query.get("alertId")??navigationMemory?.alertId??"ALR-STOCK")
  const [result,setResult] = useState<MoreResult|null>(null)
  useEffect(()=>onDepthChange?.(surface!=="M01"),[surface,onDepthChange])
  useEffect(()=>()=>onDepthChange?.(false),[onDepthChange])
  useEffect(()=>{navigationMemory={surface,stack,clientId,serviceId,courseId,accountId,alertId}},[surface,stack,clientId,serviceId,courseId,accountId,alertId])
  const navigate=(next:SurfaceId,context?:Context)=>{if(context?.clientId)setClientId(context.clientId);if(context?.serviceId)setServiceId(context.serviceId);if(context?.courseId)setCourseId(context.courseId);if(context?.accountId)setAccountId(context.accountId);if(context?.alertId)setAlertId(context.alertId);setResult(null);setStack(c=>[...c,surface]);setSurface(next)}
  const back=()=>{setResult(null);setStack(c=>{const previous=c.at(-1);setSurface(previous??"M01");return previous?c.slice(0,-1):[]})}
  const goRoot=()=>{setSurface("M01");setStack([]);setResult(null)}
  const handoff=(root:string,query:string)=>{navigationMemory={surface,stack,clientId,serviceId,courseId,accountId,alertId};window.history.replaceState(null,"",`?${query}&returnRoot=mas`);onNavigateRoot?.(root)}
  const act=(value:MoreResult,onSuccess?:(id?:string)=>void)=>{if(value.ok&&onSuccess)onSuccess(value.id);setResult(value)}
  if(surface==="M01")return <section className="more-screen more-root" data-testid="surface-M01"><div className="more-scroll" data-more-scroll><RootHeader title="Más" subtitle="Gestioná las áreas que completan la operación"/><div className="more-root-groups"><div className="more-group">{ROOT_ROWS.slice(0,3).map(r=><MoreRow key={r.id} icon={r.icon} title={r.label} detail={r.hint} onClick={()=>navigate(r.id)}/>)}</div><div className="more-group">{ROOT_ROWS.slice(3).map(r=><MoreRow key={r.id} icon={r.icon} title={r.label} detail={r.hint} onClick={()=>navigate(r.id)}/>)}</div></div></div></section>
  const contentProps:ContentProps={surface,state,clientId,serviceId,courseId,accountId,alertId,navigate,handoff,act,goRoot}
  return <section className="more-screen more-screen--deep" data-testid={`surface-${surface}`} data-surface={surface}><DetailHeader title={TITLES[surface]} onBack={back} right={["M04","M16","M27","M69"].includes(surface)?<button type="button" className="more-icon-button" aria-label="Más acciones"><MoreHorizontal size={20}/></button>:undefined}/><div className="more-scroll more-deep-scroll"><SurfaceContent {...contentProps}/>{result?<ResultBlock result={result}/>:null}</div></section>
}

type ContentProps={surface:SurfaceId;state:ReturnType<typeof moreStore.getSnapshot>;clientId:string;serviceId:string;courseId:string;accountId:string;alertId:string;navigate:(id:SurfaceId,context?:Context)=>void;handoff:(root:string,query:string)=>void;act:(result:MoreResult,onSuccess?:(id?:string)=>void)=>void;goRoot:()=>void}
function SurfaceContent(p:ContentProps){const n=Number(p.surface.slice(1));if(n<=14)return <ClientsSurface {...p}/>;if(n<=25)return <ServicesSurface {...p}/>;if(n<=42)return <CoursesSurface {...p}/>;if(n<=54)return <PresenceSurface {...p}/>;if(n<=65)return <ScheduleSurface {...p}/>;if(n<=75)return <SettingsSurface {...p}/>;return <ActivitySurface {...p}/>}
function MoreRow({icon,title,detail,value,status,onClick,disabled}:{icon?:ReactNode;title:string;detail?:string;value?:string;status?:string;onClick?:()=>void;disabled?:boolean}){return <button type="button" className="more-row" onClick={onClick} disabled={disabled||!onClick}><span className="more-row-icon">{icon}</span><span className="more-row-copy"><strong>{title}</strong>{detail?<small>{detail}</small>:null}</span><span className="more-row-trailing">{value?<b>{value}</b>:null}{status?<em>{status}</em>:null}{onClick?<ChevronRight size={18}/>:null}</span></button>}
function Section({title,children}:{title:string;children:ReactNode}){return <section className="more-section"><h2>{title}</h2><div className="more-group">{children}</div></section>}
function Hero({title,subtitle,status,action}:{title:string;subtitle?:string;status?:string;action?:ReactNode}){return <div className="more-hero"><div><span>{status}</span><h1>{title}</h1>{subtitle?<p>{subtitle}</p>:null}</div>{action}</div>}
function DataLine({label,value}:{label:string;value:string}){return <div className="more-data"><span>{label}</span><strong>{value}</strong></div>}
function StateBlock({tone="neutral",title,body,action}:{tone?:"neutral"|"warning"|"danger"|"success";title:string;body:string;action?:ReactNode}){return <div className={`more-state more-state--${tone}`} role={tone==="danger"?"alert":"status"}>{tone==="warning"||tone==="danger"?<AlertTriangle size={22}/>:tone==="success"?<Check size={22}/>:<FileClock size={22}/>}<div><strong>{title}</strong><p>{body}</p>{action}</div></div>}
function ResultBlock({result}:{result:MoreResult}){const tone=result.ok?"success":result.status==="policy_required"||result.status==="conflict"?"warning":"danger";return <StateBlock tone={tone} title={result.ok?"Cambio confirmado":result.status==="policy_required"?"Política requerida":"No se aplicó el cambio"} body={result.message}/>} 
function Toolbar({search,setSearch,onFilter,onAdd,addLabel}:{search:string;setSearch:(v:string)=>void;onFilter?:()=>void;onAdd?:()=>void;addLabel?:string}){const[open,setOpen]=useState(Boolean(search));const input=useRef<HTMLInputElement>(null);useEffect(()=>{if(open)requestAnimationFrame(()=>input.current?.focus())},[open]);return <div className={`more-toolbar ${open?"is-searching":""}`}>{open?<label className="more-search"><Search size={18}/><input ref={input} aria-label="Buscar" placeholder="Buscar" value={search} onChange={e=>setSearch(e.target.value)}/><button type="button" aria-label="Limpiar búsqueda" onClick={()=>setSearch("")}><X size={17}/></button></label>:<button type="button" className="more-icon-button" aria-label="Buscar" onClick={()=>setOpen(true)}><Search size={20}/></button>}{open?<button type="button" className="more-toolbar-text" onClick={()=>{setSearch("");setOpen(false)}}>Cancelar</button>:null}{!open&&onFilter?<button type="button" className="more-icon-button" aria-label="Filtrar" onClick={onFilter}><Filter size={20}/></button>:null}{!open&&onAdd?<button type="button" className="more-icon-button" aria-label={addLabel??"Agregar"} onClick={onAdd}><Plus size={21}/></button>:null}</div>}

function ClientsSurface(p:ContentProps){
  const[query,setQuery]=useState("");const[filterOpen,setFilterOpen]=useState(false);const[includeArchived,setIncludeArchived]=useState(false)
  const client=CLIENTES.find(i=>i.id===p.clientId)??CLIENTES[0];const meta=clientMeta(client.id)
  if(p.surface==="M02"){const rows=clientRows().filter(({client:item,meta:m})=>(includeArchived||!m.archived)&&`${item.nombre} ${item.telefono??""} ${item.correo??""}`.toLowerCase().includes(query.toLowerCase()));return <><Toolbar search={query} setSearch={setQuery} onFilter={()=>setFilterOpen(true)} onAdd={()=>p.navigate("M05")} addLabel="Registrar cliente"/>{rows.length?<Section title={includeArchived?"Todos los clientes":"Clientes activos"}>{rows.map(({client:item,meta:m})=><MoreRow key={item.id} icon={<UserRound size={20}/>} title={item.nombre} detail={item.telefono??item.correo??"Sin contacto"} status={m.archived?"Archivado":reservationsForClient(item.id).length?`${reservationsForClient(item.id).length} turnos`:"Sin actividad"} onClick={()=>p.navigate("M04",{clientId:item.id})}/>)}</Section>:<StateBlock title="Sin coincidencias" body="Probá otro nombre o restablecé los filtros." action={<button type="button" onClick={()=>{setQuery("");setIncludeArchived(false)}}>Restablecer</button>}/>}<BottomSheet open={filterOpen} onClose={()=>setFilterOpen(false)} title="Filtrar clientes"><div className="more-sheet"><label className="more-switch"><span><strong>Incluir archivados</strong><small>El histórico permanece disponible.</small></span><input type="checkbox" checked={includeArchived} onChange={e=>setIncludeArchived(e.target.checked)}/></label><PrimaryAction label="Aplicar filtros" onPress={()=>setFilterOpen(false)} fullWidth/></div></BottomSheet></>}
  if(p.surface==="M03")return <><StateBlock title="Búsqueda contextual" body="La consulta y los filtros se conservan al abrir una ficha y volver."/><Toolbar search={query} setSearch={setQuery} onFilter={()=>setFilterOpen(true)}/><Section title="Resultados"><MoreRow title="Juan Pérez" detail="Coincidencia por nombre y teléfono" onClick={()=>p.navigate("M04",{clientId:"CL01"})}/></Section><BottomSheet open={filterOpen} onClose={()=>setFilterOpen(false)} title="Filtrar resultados"><div className="more-sheet"><label className="more-switch"><span><strong>Incluir archivados</strong><small>La historia permanece disponible.</small></span><input type="checkbox" checked={includeArchived} onChange={e=>setIncludeArchived(e.target.checked)}/></label><PrimaryAction label="Aplicar filtros" onPress={()=>setFilterOpen(false)} fullWidth/></div></BottomSheet></>
  if(p.surface==="M04")return <><Hero title={client.nombre} subtitle={client.telefono??client.correo??"Sin contacto"} status={meta?.archived?"Cliente archivado":"Cliente activo"} action={<button className="more-hero-action" onClick={()=>p.navigate("M06")}>Editar</button>}/><Section title="Actividad"><MoreRow icon={<CalendarDays size={19}/>} title="Turnos y atenciones" detail={`${reservationsForClient(client.id).length} registros vinculados`} onClick={()=>p.navigate("M09")}/><MoreRow icon={<Store size={19}/>} title="Compras, pedidos y cobros" detail="Inventario y Finanzas" onClick={()=>p.navigate("M10")}/></Section><Section title="Ficha"><MoreRow title="Notas privadas" detail={`${meta?.notes.length??0} notas`} onClick={()=>p.navigate("M11")}/><MoreRow title="Contacto y consentimiento" detail={meta?.consent==="not_recorded"?"Sin decisión registrada":meta?.consent} onClick={()=>p.navigate("M12")}/><MoreRow title="Historial de identidad" detail={`${meta?.aliases.length??0} alias`} onClick={()=>p.navigate("M14")}/><MoreRow title={meta?.archived?"Restaurar cliente":"Archivar y privacidad"} detail="La historia no se elimina" onClick={()=>p.navigate("M13")}/></Section><PrimaryAction label="Crear turno" onPress={()=>p.handoff("equipo",`agendaAction=new&clientId=${client.id}`)} fullWidth/></>
  if(p.surface==="M05")return <ClientCreate onResult={r=>p.act(r,id=>id&&p.navigate("M04",{clientId:id}))} onDuplicate={id=>id&&p.navigate("M07",{clientId:id})}/>
  if(p.surface==="M06")return <ClientEdit client={client} version={meta?.version??1} onResult={p.act}/>
  if(p.surface==="M07")return <><StateBlock tone="warning" title="Posible coincidencia" body="Compará la identidad existente antes de crear otra. El borrador original permanece."/><Section title="Identidad encontrada"><MoreRow title={client.nombre} detail={`${client.telefono??"Sin teléfono"} · ${reservationsForClient(client.id).length} turnos`} onClick={()=>p.navigate("M04",{clientId:client.id})}/></Section><SecondaryAction label="Revisar fusión" onPress={()=>p.navigate("M08")} fullWidth/></>
  if(p.surface==="M08")return <MergeReview primary={client} alias={CLIENTES.find(i=>i.id!==client.id)??CLIENTES[1]} onResult={r=>p.act(r,id=>id&&p.navigate("M14",{clientId:id}))}/>
  if(p.surface==="M09"){const reservations=reservationsForClient(client.id);return <><Hero title={client.nombre} subtitle="Agenda P2 · sólo lectura desde Más"/><Section title="Turnos vinculados">{reservations.length?reservations.map(r=><MoreRow key={r.id} title={`${r.inicio.slice(8,10)}/${r.inicio.slice(5,7)} · ${r.inicio.slice(11,16)}`} detail={SERVICIOS.find(i=>i.id===r.servicioId)?.nombre??r.servicioId} status={r.estado.replace("_"," ")} onClick={()=>p.handoff("equipo",`agendaReservation=${r.id}`)}/>):<MoreRow title="Sin turnos" detail="No se crea actividad por consultar."/>}</Section></>}
  if(p.surface==="M10"){const orders=inventoryOrdersForClient(client.id),sales=financeSalesForClient(client.id);return <><Hero title={client.nombre} subtitle="Saldos separados por objeto propietario"/><Section title="Pedidos de Inventario">{orders.length?orders.map(o=><MoreRow key={o.id} title={o.number} detail={`${o.lines.length} productos`} status={o.status} onClick={()=>p.handoff("inventario",`inventorySurface=I32&orderId=${o.id}`)}/>):<MoreRow title="Sin pedidos" detail="No se crea un pedido por consultar."/>}</Section><Section title="Ventas y cobros de Finanzas">{sales.length?sales.map(s=><MoreRow key={s.id} title={s.id} detail="Venta existente P4" value={moneyArs(s.totalCents)} onClick={()=>p.handoff("finanzas",`financeSurface=F11&financeOrigin=${s.id}`)}/>):<MoreRow title="Sin ventas vinculadas" detail="No se fabrica un saldo global."/>}</Section></>}
  if(p.surface==="M11")return <ClientNotes client={client} notes={meta?.notes??[]} onResult={p.act}/>
  if(p.surface==="M12")return <ClientContact client={client} version={meta?.version??1} consent={meta?.consent??"not_recorded"} onResult={p.act}/>
  if(p.surface==="M13")return <ArchiveReview client={client} meta={meta} onResult={p.act}/>
  return <><Hero title={client.nombre} subtitle="Historial de identidad inmutable"/><Section title="Eventos">{allAuditEvents().filter(e=>e.objectId===client.id).map(e=><MoreRow key={e.id} icon={<History size={18}/>} title={e.action} detail={`${e.actor} · ${e.at.slice(0,16).replace("T"," ")}`}/>) }{meta?.aliases.map(a=><MoreRow key={a} title={`Alias ${a}`} detail={`Redirige a ${client.id}`}/>)}</Section></>
}

function ClientCreate({onResult,onDuplicate}:{onResult:(r:MoreResult)=>void;onDuplicate:(id?:string)=>void}){const[name,setName]=useState("");const[phone,setPhone]=useState("");const[email,setEmail]=useState("");const[error,setError]=useState("");const submit=()=>{if(!name.trim()){setError("El nombre es obligatorio");return}if(email&&!/^\S+@\S+\.\S+$/.test(email)){setError("Ingresá un correo válido");return}const r=createClient({nombre:name.trim(),telefono:phone||undefined,correo:email||undefined},operationId("client-create"));r.status==="duplicate"?onDuplicate(r.id):onResult(r)};return <div className="more-form"><StateBlock title="Identidad canónica" body="Se revisan coincidencias antes de crear otra persona."/><InputField id="p5-client-name" label="Nombre" value={name} onChange={v=>{setName(v);setError("")}} error={error||undefined}/><InputField id="p5-client-phone" label="Teléfono · opcional" value={phone} onChange={setPhone}/><InputField id="p5-client-email" label="Correo · opcional" type="email" value={email} onChange={setEmail}/><PrimaryAction label="Revisar y registrar" onPress={submit} disabled={!name.trim()} fullWidth/></div>}
function ClientEdit({client,version,onResult}:{client:(typeof CLIENTES)[number];version:number;onResult:(r:MoreResult)=>void}){const[name,setName]=useState(client.nombre);const[phone,setPhone]=useState(client.telefono??"");const[email,setEmail]=useState(client.correo??"");const dirty=name!==client.nombre||phone!==(client.telefono??"")||email!==(client.correo??"");return <div className="more-form"><InputField id="p5-client-edit-name" label="Nombre" value={name} onChange={setName}/><InputField id="p5-client-edit-phone" label="Teléfono" value={phone} onChange={setPhone}/><InputField id="p5-client-edit-email" label="Correo" value={email} onChange={setEmail}/><PrimaryAction label="Guardar cambios" onPress={()=>onResult(updateClient(client.id,{nombre:name,telefono:phone||undefined,correo:email||undefined},version,operationId("client-update")))} disabled={!dirty||!name.trim()} fullWidth/></div>}
function MergeReview({primary,alias,onResult}:{primary:(typeof CLIENTES)[number];alias:(typeof CLIENTES)[number];onResult:(r:MoreResult)=>void}){const meta=clientMeta(primary.id);return <><Hero title={primary.nombre} subtitle="Identidad que permanece" status="Revisión antes de fusionar"/><div className="more-compare"><DataLine label="Principal" value={`${primary.nombre} · ${primary.id}`}/><DataLine label="Alias" value={`${alias.nombre} · ${alias.id}`}/></div><Section title="Relaciones a redirigir"><MoreRow title="Reservas y atenciones" value={String(reservationsForClient(alias.id).length)}/><MoreRow title="Pedidos" value={String(inventoryOrdersForClient(alias.id).length)}/><MoreRow title="Notas privadas" value={String(clientMeta(alias.id)?.notes.length??0)}/></Section><StateBlock tone="warning" title="Historia intacta" body="La identidad secundaria queda como alias. No se eliminan eventos, obligaciones ni referencias."/><PrimaryAction label="Confirmar fusión" onPress={()=>onResult(mergeClients(primary.id,alias.id,meta?.version??1,operationId("client-merge")))} fullWidth/></>}
function ClientNotes({client,notes,onResult}:{client:(typeof CLIENTES)[number];notes:Array<{id:string;body:string;actor:string;at:string}>;onResult:(r:MoreResult)=>void}){const[body,setBody]=useState("");return <><Hero title={client.nombre} subtitle="Notas privadas según capacidades"/><div className="more-inline-editor"><label htmlFor="p5-note">Nueva nota</label><textarea id="p5-note" value={body} onChange={e=>setBody(e.target.value)} placeholder="Contexto operativo privado"/><PrimaryAction label="Agregar nota" onPress={()=>{const r=addClientNote(client.id,body,operationId("client-note"));onResult(r);if(r.ok)setBody("")}} disabled={!body.trim()} fullWidth/></div><Section title="Historial">{notes.length?notes.map(n=><MoreRow key={n.id} title={n.body} detail={`${n.actor} · ${n.at.slice(0,10)}`}/>):<MoreRow title="Sin notas privadas" detail="Agregá sólo información pertinente."/>}</Section></>}
function ClientContact({client,version,consent,onResult}:{client:(typeof CLIENTES)[number];version:number;consent:string;onResult:(r:MoreResult)=>void}){const[phone,setPhone]=useState(client.telefono??"");const[email,setEmail]=useState(client.correo??"");const[decision,setDecision]=useState(consent);return <div className="more-form"><InputField id="p5-contact-phone" label="Teléfono" value={phone} onChange={setPhone}/><InputField id="p5-contact-email" label="Correo" value={email} onChange={setEmail}/><SelectField id="p5-contact-consent" label="Consentimiento registrado" value={decision} onChange={setDecision} options={[{id:"not_recorded",label:"Sin decisión registrada"},{id:"granted",label:"Otorgado"},{id:"revoked",label:"Revocado"}]}/><StateBlock title="Sin envíos externos" body="Guardar contacto o consentimiento no envía mensajes."/><PrimaryAction label="Guardar contacto" onPress={()=>onResult(updateClientContact(client.id,{telefono:phone||undefined,correo:email||undefined},decision as "not_recorded"|"granted"|"revoked",version,operationId("client-contact")))} fullWidth/></div>}
function ArchiveReview({client,meta,onResult}:{client:(typeof CLIENTES)[number];meta:ReturnType<typeof clientMeta>;onResult:(r:MoreResult)=>void}){return <><Hero title={client.nombre} subtitle={`${reservationsForClient(client.id).length} turnos · ${inventoryOrdersForClient(client.id).length} pedidos`} status={meta?.archived?"Archivado":"Activo"}/><StateBlock tone="warning" title="La historia se conserva" body="Archivar impide usos nuevos, pero no elimina reservas, pedidos, cobros ni eventos. El borrado productivo permanece POLICY_REQUIRED."/><PrimaryAction label={meta?.archived?"Restaurar cliente":"Archivar cliente"} onPress={()=>onResult(setClientArchived(client.id,!meta?.archived,meta?.version??1,operationId("client-archive")))} fullWidth/><SecondaryAction label="Solicitud de privacidad" onPress={()=>onResult({ok:false,status:"policy_required",message:"El alcance de privacidad productiva no está aprobado"})} fullWidth/></>}

function ServicesSurface(p:ContentProps){
  const[query,setQuery]=useState("");const[filterOpen,setFilterOpen]=useState(false)
  const service=SERVICIOS.find(i=>i.id===p.serviceId)??SERVICIOS[0];const meta=p.state.serviceMeta[service.id];const future=todasLasReservas().filter(i=>i.servicioId===service.id&&i.estado==="confirmada")
  if(p.surface==="M15"){const rows=serviceRows().filter(({service:i})=>i.nombre.toLowerCase().includes(query.toLowerCase()));return <><Toolbar search={query} setSearch={setQuery} onFilter={()=>setFilterOpen(true)} onAdd={()=>p.navigate("M17",{serviceId:"SV-NEW"})} addLabel="Crear servicio"/><Section title="Catálogo único">{rows.map(({service:i,meta:m})=><MoreRow key={i.id} icon={<Store size={19}/>} title={i.nombre} detail={`${i.duracionMin} min · ${moneyArs(i.precio)}`} status={!i.activo?"Inactivo":m.publicVisible?"Público":"Oculto"} onClick={()=>p.navigate("M16",{serviceId:i.id})}/>)}</Section><button className="more-inline-link" onClick={()=>p.navigate("M21")}>Administrar categorías</button><BottomSheet open={filterOpen} onClose={()=>setFilterOpen(false)} title="Filtrar servicios"><div className="more-sheet"><p>Estado interno, visibilidad pública y categoría son dimensiones separadas.</p><PrimaryAction label="Aplicar filtros" onPress={()=>setFilterOpen(false)} fullWidth/></div></BottomSheet></>}
  if(p.surface==="M16")return <><Hero title={service.nombre} subtitle={`${service.duracionMin} min · ${moneyArs(service.precio)}`} status={`${service.activo?"Activo":"Inactivo"} · ${meta.publicVisible?"Público":"Oculto"}`} action={<button className="more-hero-action" onClick={()=>p.navigate("M17")}>Editar</button>}/><Section title="Configuración"><MoreRow title="Variantes, precio y duración" detail={`${meta.variants.length} variantes · versión ${meta.version}`} onClick={()=>p.navigate("M18")}/><MoreRow title="Profesionales habilitados" detail={`${PROFESIONALES.filter(i=>i.serviciosHabilitados.includes(service.id)&&i.estado==="activo").length} activos`} onClick={()=>p.navigate("M19")}/><MoreRow title="Disponibilidad pública" detail={meta.publicVisible?"Visible en Cliente demo":"Oculto"} onClick={()=>p.navigate("M20")}/></Section><Section title="Control"><MoreRow title="Impacto de cambios" detail={`${future.length} reservas futuras`} onClick={()=>p.navigate("M23")}/><MoreRow title={service.activo?"Desactivar servicio":"Reactivar servicio"} detail="El histórico permanece" onClick={()=>p.navigate("M24")}/><MoreRow title="Historia y uso" detail={`${meta.history.length} versiones`} onClick={()=>p.navigate("M25")}/></Section></>
  if(p.surface==="M17")return <ServiceEdit service={p.serviceId==="SV-NEW"?undefined:service} meta={p.serviceId==="SV-NEW"?undefined:meta} onResult={r=>p.act(r,id=>id&&p.navigate("M16",{serviceId:id}))} onDuplicate={()=>p.navigate("M22")} onReview={()=>p.navigate("M23")}/>
  if(p.surface==="M18")return <ServiceVariants service={service} meta={meta} onResult={p.act} onReview={()=>p.navigate("M23")}/>
  if(p.surface==="M19")return <ProfessionalEligibility service={service} version={meta.version} onResult={p.act} onReview={()=>p.navigate("M23")}/>
  if(p.surface==="M20")return <><Hero title={service.nombre} subtitle={meta.description} status={meta.publicVisible?"Visible en Cliente demo":"No publicado"}/><StateBlock title="Publicación demo" body="Afecta nuevas reservas públicas; no despliega una web externa."/><PrimaryAction label={meta.publicVisible?"Ocultar servicio":"Publicar servicio en demo"} onPress={()=>p.act(setServicePublic(service.id,!meta.publicVisible,meta.version,operationId("service-public")))} fullWidth/><SecondaryAction label="Ver en vista Cliente" onPress={()=>p.navigate("M46")} fullWidth/></>
  if(p.surface==="M21")return <CategoryEditor/>
  if(p.surface==="M22")return <><StateBlock tone="warning" title="Servicio similar encontrado" body="Usá el catálogo existente o diferenciá nombre, duración y categoría."/><Section title="Coincidencias">{SERVICIOS.map(i=><MoreRow key={i.id} title={i.nombre} detail={`${i.duracionMin} min · ${moneyArs(i.precio)}`} onClick={()=>p.navigate("M16",{serviceId:i.id})}/>)}</Section></>
  if(p.surface==="M23")return <ServiceImpact service={service} future={future} onHandoff={id=>p.handoff("equipo",`agendaReservation=${id}`)}/>
  if(p.surface==="M24")return <><Hero title={service.nombre} status={service.activo?"Activo":"Inactivo"}/><StateBlock tone={future.length?"warning":"neutral"} title={future.length?`${future.length} reservas futuras requieren resolución`:"Sin compromisos futuros"} body="Desactivar bloquea nuevas reservas y mantiene snapshots históricos."/><PrimaryAction label={service.activo?"Revisar desactivación":"Reactivar servicio"} onPress={()=>future.length?p.navigate("M23"):p.act(updateService(service.id,{activo:!service.activo},meta.version,operationId("service-status")))} fullWidth/></>
  return <><Hero title={service.nombre} subtitle="Historia inmutable y vínculos propietarios"/><Section title="Versiones">{meta.history.map(e=><MoreRow key={e.version} icon={<History size={18}/>} title={`Versión ${e.version} · ${e.detail}`} detail={`${e.duration} min · ${moneyArs(e.price)}`}/>)}</Section><Section title="Usos P2">{todasLasReservas().filter(i=>i.servicioId===service.id).slice(0,6).map(r=><MoreRow key={r.id} title={r.id} detail={`${r.inicio.slice(0,16).replace("T"," ")} · ${r.estado}`} onClick={()=>p.handoff("equipo",`agendaReservation=${r.id}`)}/>)}</Section></>
}

function ServiceEdit({service,meta,onResult,onDuplicate,onReview}:{service?:(typeof SERVICIOS)[number];meta?:ReturnType<typeof moreStore.getSnapshot>["serviceMeta"][string];onResult:(r:MoreResult)=>void;onDuplicate:()=>void;onReview:()=>void}){const existing=Boolean(service&&meta);const[name,setName]=useState(service?.nombre??"");const[duration,setDuration]=useState(String(service?.duracionMin??30));const[price,setPrice]=useState(service?String(service.precio/100):"");const[category,setCategory]=useState(meta?.category??"Cortes");const[description,setDescription]=useState(meta?.description??"");const submit=()=>{const d=Number(duration),pr=Math.round(Number(price)*100);if(!service||!meta){const r=createService({nombre:name,duracionMin:d,precio:pr,activo:true,category,description},operationId("service-create"));r.status==="duplicate"?onDuplicate():onResult(r);return}if(d!==service.duracionMin&&todasLasReservas().some(i=>i.servicioId===service.id&&i.estado==="confirmada")){onReview();return}onResult(updateService(service.id,{nombre:name,duracionMin:d,precio:pr},meta.version,operationId("service-update")))};return <div className="more-form"><InputField id="p5-service-name" label="Nombre" value={name} onChange={setName}/><SelectField id="p5-service-category" label="Categoría" value={category} onChange={setCategory} options={[{id:"Cortes",label:"Cortes"},{id:"Barba",label:"Barba"},{id:"Formación",label:"Formación"}]}/><InputField id="p5-service-duration" label="Duración exacta · minutos" type="number" value={duration} onChange={setDuration}/><InputField id="p5-service-price" label="Precio ARS" type="number" value={price} onChange={setPrice}/><label className="more-textarea"><span>Descripción</span><textarea value={description} onChange={e=>setDescription(e.target.value)}/></label><PrimaryAction label={existing?"Revisar y guardar versión":"Crear servicio interno"} onPress={submit} disabled={!name.trim()||Number(duration)<=0||Number(price)<0} fullWidth/></div>}
function ServiceVariants({service,meta,onResult,onReview}:{service:(typeof SERVICIOS)[number];meta:ReturnType<typeof moreStore.getSnapshot>["serviceMeta"][string];onResult:(r:MoreResult)=>void;onReview:()=>void}){const[name,setName]=useState("Terminación premium");const[duration,setDuration]=useState(String(service.duracionMin+10));const[price,setPrice]=useState(String((service.precio+500000)/100));const hasImpact=todasLasReservas().some(item=>item.servicioId===service.id&&item.estado==="confirmada");return <><StateBlock title="Defaults explícitos" body={`Servicio base: ${service.duracionMin} min · ${moneyArs(service.precio)}.`}/><div className="more-form"><InputField id="p5-variant-name" label="Nombre de variante" value={name} onChange={setName}/><InputField id="p5-variant-duration" label="Duración · minutos" type="number" value={duration} onChange={setDuration}/><InputField id="p5-variant-price" label="Precio ARS" type="number" value={price} onChange={setPrice}/><PrimaryAction label={hasImpact?"Revisar variante e impactos":"Guardar variante"} onPress={()=>hasImpact?onReview():onResult(addServiceVariant(service.id,{name,durationMinutes:Number(duration),priceMinor:Math.round(Number(price)*100)},meta.version,operationId("service-variant")))} fullWidth/></div>{meta.variants.length?<Section title="Variantes actuales">{meta.variants.map(v=><MoreRow key={v.id} title={v.name} detail={`${v.durationMinutes} min · ${moneyArs(v.priceMinor)}`}/>)}</Section>:null}</>}
function ProfessionalEligibility({service,version,onResult,onReview}:{service:(typeof SERVICIOS)[number];version:number;onResult:(r:MoreResult)=>void;onReview:()=>void}){const initial=PROFESIONALES.filter(i=>i.serviciosHabilitados.includes(service.id)).map(i=>i.id);const[selected,setSelected]=useState(()=>new Set(initial));const changed=initial.length!==selected.size||initial.some(id=>!selected.has(id));const hasImpact=changed&&todasLasReservas().some(item=>item.servicioId===service.id&&item.estado==="confirmada");return <><Section title="Profesionales reales">{PROFESIONALES.map(pr=><label key={pr.id} className={`more-check-row ${pr.estado==="inactivo"?"is-disabled":""}`}><span><strong>{pr.nombre}</strong><small>{pr.responsabilida} · {pr.estado}</small></span><input type="checkbox" disabled={pr.estado==="inactivo"} checked={selected.has(pr.id)} onChange={()=>setSelected(c=>{const n=new Set(c);n.has(pr.id)?n.delete(pr.id):n.add(pr.id);return n})}/></label>)}</Section><PrimaryAction label={hasImpact?"Revisar profesionales afectados":"Guardar elegibilidad"} onPress={()=>hasImpact?onReview():onResult(updateServiceEligibility(service.id,[...selected],version,operationId("service-eligibility")))} disabled={selected.size===0||!changed} fullWidth/></>}
function CategoryEditor(){const[categories,setCategories]=useState(["Cortes","Barba"]);const[name,setName]=useState("");return <><div className="more-inline-editor"><InputField id="p5-category-name" label="Nueva categoría" value={name} onChange={setName}/><PrimaryAction label="Agregar categoría" onPress={()=>{if(name.trim()&&!categories.includes(name.trim())){setCategories(c=>[...c,name.trim()]);setName("")}}} disabled={!name.trim()} fullWidth/></div><Section title="Categorías">{categories.map(c=><MoreRow key={c} title={c} detail={`${serviceRows().filter(({meta})=>meta.category===c).length} servicios`}/>)}</Section></>}
function ServiceImpact({service,future,onHandoff}:{service:(typeof SERVICIOS)[number];future:ReturnType<typeof todasLasReservas>;onHandoff:(id:string)=>void}){return <><div className="more-compare"><DataLine label="Antes" value={`${service.duracionMin} min · ${moneyArs(service.precio)}`}/><DataLine label="Después" value="Cambio propuesto conservado en borrador"/></div><Section title="Compromisos afectados">{future.length?future.map(r=><MoreRow key={r.id} icon={<AlertTriangle size={18}/>} title={r.id} detail={`${CLIENTES.find(i=>i.id===r.clienteId)?.nombre} · ${r.inicio.slice(0,16).replace("T"," ")}`} status="Sin resolver" onClick={()=>onHandoff(r.id)}/>):<MoreRow title="Sin afectados" detail="La versión nueva sólo aplica a operaciones futuras."/>}</Section><StateBlock tone={future.length?"warning":"success"} title={future.length?"Resolución requerida en Agenda":"Cambio listo para revisión"} body={future.length?"Cada turno se resuelve mediante P2; no se mueve ni cancela automáticamente.":"No hay compromisos que reubicar."}/></>}

function CoursesSurface(p:ContentProps){
  const[query,setQuery]=useState("");const course=p.state.courses.find(i=>i.id===p.courseId)??p.state.courses[0]
  const session=course?.sessions[0];const enrollment=course?.enrollments[0]
  if(p.surface==="M26")return <><Toolbar search={query} setSearch={setQuery} onFilter={()=>p.navigate("M42")} onAdd={()=>p.navigate("M28",{courseId:"CRS-NEW"})} addLabel="Crear curso"/><Section title="Próximos y en curso">{p.state.courses.filter(i=>i.name.toLowerCase().includes(query.toLowerCase())&&!i.status.match(/completed|archived/)).map(i=><MoreRow key={i.id} icon={<GraduationCap size={19}/>} title={i.name} detail={`${i.sessions.length} sesiones · ${i.enrollments.filter(e=>e.status==="enrolled").length}/${i.capacity} plazas`} status={i.status.replace("_"," ")} onClick={()=>p.navigate("M27",{courseId:i.id})}/>)}</Section><button className="more-inline-link" onClick={()=>p.navigate("M42")}>Ver cursos históricos</button></>
  if(!course)return <StateBlock tone="danger" title="Curso no disponible" body="Volvé al listado y elegí un curso existente."/>
  if(p.surface==="M27")return <><Hero title={course.name} subtitle={course.objective} status={`${course.status.replace("_"," ")} · ${course.publication}`} action={<button className="more-hero-action" onClick={()=>p.navigate("M28")}>Editar</button>}/><Section title="Configuración"><MoreRow title="Programa y contenidos" detail={`${course.program.length} secciones`} onClick={()=>p.navigate("M29")}/><MoreRow title="Sesiones" detail={`${course.sessions.length} programadas`} onClick={()=>p.navigate("M30")}/><MoreRow title="Inscripciones" detail={`${course.enrollments.filter(e=>e.status==="enrolled").length}/${course.capacity} plazas`} onClick={()=>p.navigate("M34")}/></Section><Section title="Seguimiento"><MoreRow title="Finalización y progreso" detail="Derivado de asistencia real" onClick={()=>p.navigate("M39")}/><MoreRow title="Situación económica" detail={course.paid?"Política pendiente":"Curso gratuito"} onClick={()=>p.navigate("M41")}/><MoreRow title="Cancelar, finalizar o archivar" detail="Revisión de impactos" onClick={()=>p.navigate("M40")}/></Section></>
  if(p.surface==="M28")return <CourseEditor course={p.courseId==="CRS-NEW"?undefined:course} onResult={r=>p.act(r,id=>id&&p.navigate("M27",{courseId:id}))}/>
  if(p.surface==="M29")return <ProgramEditor course={course} onResult={p.act}/>
  if(p.surface==="M30")return <><div className="more-calendar-rail"><button>‹</button><strong>Sesiones del curso</strong><button>›</button></div><Section title="Cronograma">{course.sessions.length?course.sessions.map(s=><MoreRow key={s.id} icon={<CalendarDays size={18}/>} title={`${s.startsAt.slice(8,10)}/${s.startsAt.slice(5,7)} · ${s.startsAt.slice(11,16)}`} detail={`${PROFESIONALES.find(i=>i.id===s.instructorId)?.nombre??s.instructorId} · ${s.resourceId}`} status={s.status} onClick={()=>p.navigate("M32")}/>):<MoreRow title="Sin sesiones" detail="Creá la primera sesión sin inventar fechas."/>}</Section><PrimaryAction label="Crear sesión" onPress={()=>p.navigate("M31")} fullWidth/>{session?<SecondaryAction label="Registrar asistencia" onPress={()=>p.navigate("M38")} fullWidth/>:null}</>
  if(p.surface==="M31")return <CourseSessionEditor course={course} onResult={p.act} onConflict={()=>p.navigate("M62")} onPicker={()=>p.navigate("M33")}/>
  if(p.surface==="M32")return session?<SessionReschedule course={course} session={session} onResult={p.act} onConflict={()=>p.navigate("M62")}/>:<StateBlock title="Sin sesión" body="No hay una sesión para reprogramar."/>
  if(p.surface==="M33")return <><StateBlock title="Disponibilidad derivada" body="Se usan StaffID existentes y ocupación exacta [inicio, fin)."/><Section title="Instructores">{PROFESIONALES.map(i=><MoreRow key={i.id} title={i.nombre} detail={`${i.responsabilida} · ${i.estado}`} status={i.estado==="activo"?"Elegible":"No elegible"}/>)}</Section><Section title="Recursos"><MoreRow title="Sillón 1" detail="Recurso compartido" status="Disponible"/><MoreRow title="Aula práctica" detail="Recurso de curso" status="Disponible"/></Section></>
  if(p.surface==="M34")return <><Toolbar search={query} setSearch={setQuery} onAdd={()=>p.navigate("M35")} addLabel="Inscribir participante"/><Section title="Inscriptos">{course.enrollments.filter(e=>e.status==="enrolled").map(e=><MoreRow key={e.id} title={CLIENTES.find(i=>i.id===e.clientId)?.nombre??e.clientId} detail={e.id} status="Inscripto" onClick={()=>p.navigate("M36",{clientId:e.clientId})}/>)}</Section><button className="more-inline-link" onClick={()=>p.navigate("M37")}>Capacidad y lista de espera</button></>
  if(p.surface==="M35")return <EnrollmentEditor course={course} onResult={p.act}/>
  if(p.surface==="M36")return enrollment?<><Hero title={CLIENTES.find(i=>i.id===p.clientId)?.nombre??CLIENTES.find(i=>i.id===enrollment.clientId)?.nombre??enrollment.clientId} subtitle={course.name} status={enrollment.status}/><Section title="Seguimiento"><MoreRow title="Asistencia" detail={`${Object.values(enrollment.attendance).filter(v=>v==="present").length} presentes`} onClick={()=>p.navigate("M38")}/><MoreRow title="Situación económica" detail={course.paid?"Requiere Finanzas":"Sin obligación"} onClick={()=>p.navigate("M41")}/></Section></>:<StateBlock title="Sin inscripción" body="Elegí una inscripción existente."/>
  if(p.surface==="M37")return <><div className="more-capacity"><strong>{course.enrollments.filter(e=>e.status==="enrolled").length}</strong><span>de {course.capacity} plazas confirmadas</span></div><StateBlock tone={course.enrollments.filter(e=>e.status==="enrolled").length>=course.capacity?"warning":"success"} title={course.enrollments.filter(e=>e.status==="enrolled").length>=course.capacity?"Cupo completo":"Hay plazas disponibles"} body="La promoción desde espera no es automática. Sin política aprobada, la plaza permanece bloqueada."/><PrimaryAction label="Gestionar espera" onPress={()=>p.act({ok:false,status:"policy_required",message:"La prioridad y aceptación de lista de espera no están definidas"})} fullWidth/></>
  if(p.surface==="M38")return session?<AttendanceEditor course={course} sessionId={session.id} onResult={p.act}/>:<StateBlock title="Sin sesión" body="La asistencia se registra sobre una sesión real."/>
  if(p.surface==="M39"){const complete=course.sessions.length>0&&course.enrollments.every(e=>Object.values(e.attendance).every(v=>v!=="pending"));return <><Section title="Progreso por participante">{course.enrollments.map(e=>{const values=Object.values(e.attendance),done=values.filter(v=>v!=="pending").length;return <MoreRow key={e.id} title={CLIENTES.find(i=>i.id===e.clientId)?.nombre??e.clientId} detail={`${done}/${values.length} sesiones registradas`} status={done===values.length?"Completo":"Pendiente"}/>})}</Section><StateBlock tone={complete?"success":"warning"} title={complete?"Curso listo para finalizar":"Asistencias pendientes"} body="El progreso depende de sesiones y asistencia, no del pago. No se emiten certificados legales."/></>}
  if(p.surface==="M40")return <><Hero title={course.name} status={course.status}/><Section title="Impactos"><MoreRow title="Participantes" value={String(course.enrollments.length)} /><MoreRow title="Sesiones futuras" value={String(course.sessions.filter(s=>s.status==="scheduled").length)}/><MoreRow title="Obligaciones P4" value={course.paid?"Revisar":"Ninguna"}/></Section><StateBlock tone="warning" title="Sin reembolsos ni avisos ficticios" body="Cancelar docencia libera recursos; cualquier obligación se resuelve en Finanzas."/><PrimaryAction label="Cancelar docencia" onPress={()=>p.act(setCourseStatus(course.id,"cancelled",course.version,operationId("course-cancel")))} disabled={course.status==="cancelled"||course.status==="archived"} fullWidth/><SecondaryAction label="Finalizar curso" onPress={()=>p.act(setCourseStatus(course.id,"completed",course.version,operationId("course-complete")))} disabled={course.status==="completed"||course.status==="archived"} fullWidth/><SecondaryAction label="Archivar curso" onPress={()=>p.act(setCourseStatus(course.id,"archived",course.version,operationId("course-archive")))} disabled={!['cancelled','completed'].includes(course.status)} fullWidth/></>
  if(p.surface==="M41")return <><Hero title={course.name} subtitle="Situación económica separada de la inscripción" status={course.paid?"POLICY_REQUIRED":"Gratuito"}/>{course.paid?<StateBlock tone="warning" title="Tarifa y cobro sin definir" body="P5 no crea ventas ni cobros. Definí contrato comercial antes de abrir Finanzas."/>:<StateBlock title="Curso gratuito" body="No existe obligación financiera vinculada."/>}<SecondaryAction label="Consultar Finanzas" onPress={()=>p.handoff("finanzas",`financeSurface=F03&courseId=${course.id}`)} fullWidth/></>
  return <><Section title="Finalizados y archivados">{p.state.courses.filter(i=>["completed","archived","cancelled"].includes(i.status)).length?p.state.courses.filter(i=>["completed","archived","cancelled"].includes(i.status)).map(i=><MoreRow key={i.id} title={i.name} detail={`${i.sessions.length} sesiones · programa snapshot`} status={i.status}/>):<MoreRow title="Sin cursos históricos" detail="Los borradores no aparecen aquí."/>}</Section></>
}

function CourseEditor({course,onResult}:{course?:ReturnType<typeof moreStore.getSnapshot>["courses"][number];onResult:(r:MoreResult)=>void}){const[name,setName]=useState(course?.name??"");const[objective,setObjective]=useState(course?.objective??"");const[capacity,setCapacity]=useState(String(course?.capacity??8));const[paid,setPaid]=useState(course?.paid??false);return <div className="more-form"><InputField id="p5-course-name" label="Nombre" value={name} onChange={setName}/><label className="more-textarea"><span>Objetivo</span><textarea value={objective} onChange={e=>setObjective(e.target.value)}/></label><InputField id="p5-course-capacity" label="Capacidad" type="number" value={capacity} onChange={setCapacity}/><label className="more-switch"><span><strong>Curso pago</strong><small>La tarifa y el cobro requieren política.</small></span><input type="checkbox" checked={paid} onChange={e=>setPaid(e.target.checked)}/></label>{paid?<StateBlock tone="warning" title="POLICY_REQUIRED" body="Podés guardar el borrador, pero no cobrar ni publicar una tarifa."/>:null}<PrimaryAction label="Guardar curso borrador" onPress={()=>onResult(createCourse({name,objective,capacity:Number(capacity),paid},operationId("course-create")))} disabled={!name.trim()||Number(capacity)<0} fullWidth/></div>}
function ProgramEditor({course,onResult}:{course:ReturnType<typeof moreStore.getSnapshot>["courses"][number];onResult:(r:MoreResult)=>void}){const[sections,setSections]=useState<ProgramSection[]>(course.program);const[title,setTitle]=useState("");const[topic,setTopic]=useState("");const[selectedSection,setSelectedSection]=useState(course.program[0]?.id??"");const move=(index:number,dir:number)=>setSections(c=>{const next=[...c],target=index+dir;if(target<0||target>=next.length)return c;[next[index],next[target]]=[next[target],next[index]];return next});const addSection=()=>{if(!title.trim())return;const id=`SEC-${Date.now()}`;setSections(c=>[...c,{id,title:title.trim(),topics:[]}]);setSelectedSection(id);setTitle("")};const addTopic=()=>{if(!topic.trim()||!selectedSection)return;setSections(c=>c.map(section=>section.id===selectedSection?{...section,topics:[...section.topics,topic.trim()]}:section));setTopic("")};return <><div className="more-inline-editor"><InputField id="p5-program-section" label="Nueva sección" value={title} onChange={setTitle}/><PrimaryAction label="Agregar sección" onPress={addSection} disabled={!title.trim()} fullWidth/></div>{sections.length?<div className="more-inline-editor"><SelectField id="p5-program-topic-section" label="Sección del tema" value={selectedSection} onChange={setSelectedSection} options={sections.map(section=>({id:section.id,label:section.title}))}/><InputField id="p5-program-topic" label="Nuevo tema o contenido" value={topic} onChange={setTopic}/><PrimaryAction label="Agregar tema" onPress={addTopic} disabled={!topic.trim()||!selectedSection} fullWidth/></div>:null}<Section title="Programa ordenado">{sections.map((s,index)=><div className="more-program-row" key={s.id}><span><strong>{s.title}</strong><small>{s.topics.join(" · ")||"Sin temas"}</small></span><button aria-label={`Mover ${s.title} arriba`} onClick={()=>move(index,-1)}>↑</button><button aria-label={`Mover ${s.title} abajo`} onClick={()=>move(index,1)}>↓</button></div>)}</Section><PrimaryAction label="Guardar versión del programa" onPress={()=>onResult(updateCourseProgram(course.id,sections,course.version,operationId("program-update")))} fullWidth/></>}
function CourseSessionEditor({course,onResult,onConflict,onPicker}:{course:ReturnType<typeof moreStore.getSnapshot>["courses"][number];onResult:(r:MoreResult)=>void;onConflict:()=>void;onPicker:()=>void}){const[date,setDate]=useState("2026-10-26");const[start,setStart]=useState("10:00");const[duration,setDuration]=useState("90");const[instructor,setInstructor]=useState(course.instructorId??"ST01");const end=new Date(`${date}T${start}:00-03:00`);end.setMinutes(end.getMinutes()+Number(duration));const endsAt=`${date}T${String(end.getHours()).padStart(2,"0")}:${String(end.getMinutes()).padStart(2,"0")}:00-03:00`;const conflicts=sessionConflicts(`${date}T${start}:00-03:00`,endsAt,instructor);const submit=()=>{const r=createCourseSession(course.id,{startsAt:`${date}T${start}:00-03:00`,endsAt,instructorId:instructor,resourceId:"SILLON-01"},course.version,operationId("session-create"));r.status==="conflict"?onConflict():onResult(r)};return <div className="more-form"><InputField id="p5-session-date" label="Fecha" type="date" value={date} onChange={setDate}/><InputField id="p5-session-start" label="Hora de inicio" type="time" value={start} onChange={setStart}/><InputField id="p5-session-duration" label="Duración · minutos" type="number" value={duration} onChange={setDuration}/><SelectField id="p5-session-instructor" label="Instructor" value={instructor} onChange={setInstructor} options={PROFESIONALES.filter(i=>i.estado==="activo"&&i.responsabilida==="Barbero").map(i=>({id:i.id,label:i.nombre}))}/><button className="more-inline-link" onClick={onPicker}>Revisar instructores y recursos</button>{conflicts.length?<StateBlock tone="warning" title={`${conflicts.length} conflicto(s)`} body={`${conflicts[0].type} ${conflicts[0].id} ocupa la franja.`}/>:<StateBlock tone="success" title="Franja disponible" body="Agenda, cursos y recurso no se superponen."/>}<PrimaryAction label="Revisar y crear sesión" onPress={submit} fullWidth/></div>}
function SessionReschedule({course,session,onResult,onConflict}:{course:ReturnType<typeof moreStore.getSnapshot>["courses"][number];session:ReturnType<typeof moreStore.getSnapshot>["courses"][number]["sessions"][number];onResult:(r:MoreResult)=>void;onConflict:()=>void}){const[date,setDate]=useState(session.startsAt.slice(0,10));const[start,setStart]=useState(session.startsAt.slice(11,16));const[instructor,setInstructor]=useState(session.instructorId);const duration=Math.round((new Date(session.endsAt).getTime()-new Date(session.startsAt).getTime())/60000);const startsAt=`${date}T${start}:00-03:00`;const endDate=new Date(startsAt);endDate.setMinutes(endDate.getMinutes()+duration);const endsAt=`${date}T${String(endDate.getHours()).padStart(2,"0")}:${String(endDate.getMinutes()).padStart(2,"0")}:00-03:00`;const conflicts=sessionConflicts(startsAt,endsAt,instructor,session.id);return <><div className="more-compare"><DataLine label="Antes" value={session.startsAt.slice(0,16).replace("T"," ")}/><DataLine label="Después" value={`${date} ${start}`}/></div><div className="more-form"><InputField id="p5-reschedule-date" label="Nueva fecha" type="date" value={date} onChange={setDate}/><InputField id="p5-reschedule-time" label="Nueva hora" type="time" value={start} onChange={setStart}/><SelectField id="p5-reschedule-instructor" label="Instructor" value={instructor} onChange={setInstructor} options={PROFESIONALES.filter(item=>item.estado==="activo"&&item.responsabilida==="Barbero").map(item=>({id:item.id,label:item.nombre}))}/></div><StateBlock tone="warning" title={`${course.enrollments.length} participantes afectados`} body="No se enviarán mensajes reales. La sesión se versiona tras revalidar recursos."/>{conflicts.length?<SecondaryAction label="Revisar conflictos" onPress={onConflict} fullWidth/>:<PrimaryAction label="Confirmar reprogramación" onPress={()=>onResult(updateCourseSession(course.id,session.id,{startsAt,endsAt,instructorId:instructor,resourceId:session.resourceId},course.version,operationId("session-reschedule")))} fullWidth/>}</>}
function EnrollmentEditor({course,onResult}:{course:ReturnType<typeof moreStore.getSnapshot>["courses"][number];onResult:(r:MoreResult)=>void}){const[clientId,setClientId]=useState("CL03");return <div className="more-form"><SelectField id="p5-enrollment-client" label="Cliente canónico" value={clientId} onChange={setClientId} options={CLIENTES.map(i=>({id:i.id,label:i.nombre}))}/><DataLine label="Curso" value={course.name}/><DataLine label="Cupo" value={`${course.enrollments.filter(e=>e.status==="enrolled").length}/${course.capacity}`}/><StateBlock title="Situación comercial separada" body="Inscribir no crea venta, obligación ni cobro."/><PrimaryAction label="Registrar inscripción" onPress={()=>onResult(enrollClient(course.id,clientId,operationId("enrollment")))} fullWidth/></div>}
function AttendanceEditor({course,sessionId,onResult}:{course:ReturnType<typeof moreStore.getSnapshot>["courses"][number];sessionId:string;onResult:(r:MoreResult)=>void}){const[values,setValues]=useState<Record<string,"pending"|"present"|"absent">>(()=>Object.fromEntries(course.enrollments.filter(e=>e.status==="enrolled").map(e=>[e.clientId,e.attendance[sessionId]??"pending"])));return <><Section title="Participantes">{course.enrollments.filter(e=>e.status==="enrolled").map(e=><div className="more-attendance" key={e.id}><strong>{CLIENTES.find(i=>i.id===e.clientId)?.nombre??e.clientId}</strong><select aria-label={`Asistencia de ${e.clientId}`} value={values[e.clientId]} onChange={event=>setValues(c=>({...c,[e.clientId]:event.target.value as typeof values[string]}))}><option value="pending">Pendiente</option><option value="present">Presente</option><option value="absent">Ausente</option></select></div>)}</Section><PrimaryAction label="Guardar asistencia de la sesión" onPress={()=>onResult(saveAttendance(course.id,sessionId,values,operationId("attendance")))} fullWidth/></>}

function PresenceSurface(p:ContentProps){
  const profile=p.state.profile;const promo=p.state.promotions[0]
  if(p.surface==="M43")return <><Hero title="Presencia pública" subtitle="Borrador y publicación demo permanecen separados" status={profile.draftVersion===profile.publishedVersion?"Publicado al día":`Borrador v${profile.draftVersion} sin publicar`}/><Section title="Perfil"><MoreRow icon={<Store size={19}/>} title="Información pública" detail={profile.draft.description} onClick={()=>p.navigate("M44")}/><MoreRow title="Galería pública" detail={`${profile.draft.media.length} imágenes en borrador`} onClick={()=>p.navigate("M45")}/><MoreRow title="Vista previa Cliente" detail="Comparar borrador con publicado" onClick={()=>p.navigate("M46")}/><MoreRow title="Revisar y publicar" detail={`Publicado v${profile.publishedVersion}`} onClick={()=>p.navigate("M47")}/></Section><Section title="Promociones"><MoreRow icon={<Megaphone size={19}/>} title="Promociones" detail={`${p.state.promotions.length} reglas versionadas`} onClick={()=>p.navigate("M48")}/></Section></>
  if(p.surface==="M44")return <PublicProfileEditor profile={profile} onResult={p.act} onGallery={()=>p.navigate("M45")}/>
  if(p.surface==="M45")return <MediaGallery profile={profile} onResult={p.act}/>
  if(p.surface==="M46")return <PublicPreview profile={profile}/>
  if(p.surface==="M47")return <><div className="more-version-grid"><div><span>Borrador</span><strong>v{profile.draftVersion}</strong><p>{profile.draft.description}</p></div><div><span>Publicado demo</span><strong>v{profile.publishedVersion}</strong><p>{profile.published.description}</p></div></div><StateBlock title="Publicación sólo demo" body="Confirmar actualiza la vista Cliente local y el evento de auditoría. No despliega una web externa."/><PrimaryAction label="Publicar versión demo" onPress={()=>p.act(publishProfile(profile.draftVersion,operationId("profile-publish")))} disabled={profile.draftVersion===profile.publishedVersion} fullWidth/></>
  if(p.surface==="M48")return <><Toolbar search="" setSearch={()=>{}} onAdd={()=>p.navigate("M49")} addLabel="Crear promoción"/><Section title="Borradores y activas">{p.state.promotions.map(pr=><MoreRow key={pr.id} title={pr.name} detail={`${pr.benefit} · ${pr.startsAt} a ${pr.endsAt}`} status={pr.status} onClick={()=>p.navigate("M52")}/>)}</Section>{promo?<><SecondaryAction label="Pausar o finalizar" onPress={()=>p.navigate("M53")} fullWidth/><SecondaryAction label="Historial de promoción" onPress={()=>p.navigate("M54")} fullWidth/></>:null}</>
  if(p.surface==="M49")return <PromotionEditor onResult={p.act} onTargets={()=>p.navigate("M50")} onConditions={()=>p.navigate("M51")}/>
  if(p.surface==="M50")return <PromotionTargets/>
  if(p.surface==="M51")return <PromotionConditions promo={promo}/>
  if(p.surface==="M52")return promo?<><Hero title={promo.publicText} subtitle={`${promo.startsAt} — ${promo.endsAt}`} status={promo.status}/><div className="more-compare"><DataLine label="Precio base" value={moneyArs(SERVICIOS[0].precio)}/><DataLine label="Beneficio" value={promo.benefit}/></div>{promo.policyApproved?<PrimaryAction label="Activar promoción" onPress={()=>p.act(activatePromotion(promo.id,promo.version,operationId("promo-activate")))} fullWidth/>:<StateBlock tone="warning" title="POLICY_REQUIRED" body="No se calcula un precio final ni se activa sin regla de beneficio y acumulación aprobada."/>}</>:<StateBlock title="Sin promoción" body="Creá un borrador para previsualizarlo."/>
  if(p.surface==="M53")return promo?<><Hero title={promo.name} status={promo.status}/><StateBlock title="Historia preservada" body="Pausar o finalizar impide nuevas aplicaciones y no altera descuentos ya registrados en P4."/><PrimaryAction label="Pausar promoción" onPress={()=>p.act(setPromotionStatus(promo.id,"paused",promo.version,operationId("promo-pause")))} disabled={promo.status!=="active"} fullWidth/><SecondaryAction label="Finalizar promoción" onPress={()=>p.act(setPromotionStatus(promo.id,"ended",promo.version,operationId("promo-end")))} disabled={promo.status==="ended"} fullWidth/></>:null
  return <><Section title="Versiones y aplicaciones reales"><MoreRow title="Versión inicial" detail="Borrador creado · sin ventas afectadas"/><MoreRow title="Aplicaciones P4" detail="Sin aplicaciones confirmadas" value="0"/></Section></>
}

function p3PublicProducts(){return inventoryStore.getSnapshot().articles.filter(a=>a.usages.includes("sale")).slice(0,5)}
function PublicProfileEditor({profile,onResult,onGallery}:{profile:ReturnType<typeof moreStore.getSnapshot>["profile"];onResult:(r:MoreResult)=>void;onGallery:()=>void}){const[name,setName]=useState(profile.draft.name);const[description,setDescription]=useState(profile.draft.description);const[phone,setPhone]=useState(profile.draft.phone);const[address,setAddress]=useState(profile.draft.address);const[website,setWebsite]=useState(profile.draft.website);return <div className="more-form"><StateBlock title={`Editando borrador v${profile.draftVersion}`} body={`La publicación demo permanece en v${profile.publishedVersion}.`}/><InputField id="p5-public-name" label="Nombre público" value={name} onChange={setName}/><label className="more-textarea"><span>Descripción pública</span><textarea value={description} onChange={e=>setDescription(e.target.value)}/></label><InputField id="p5-public-phone" label="Contacto público" value={phone} onChange={setPhone}/><InputField id="p5-public-address" label="Ubicación pública" value={address} onChange={setAddress}/><InputField id="p5-public-website" label="Enlace" value={website} onChange={setWebsite}/><SecondaryAction label="Gestionar galería" onPress={onGallery} fullWidth/><PrimaryAction label="Guardar borrador" onPress={()=>onResult(updateProfileDraft({name,description,phone,address,website},operationId("profile-draft")))} fullWidth/></div>}
function MediaGallery({profile,onResult}:{profile:ReturnType<typeof moreStore.getSnapshot>["profile"];onResult:(r:MoreResult)=>void}){const input=useRef<HTMLInputElement>(null);const add=(files:FileList|null)=>{if(!files?.length)return;const media=[...profile.draft.media,...Array.from(files).map((file,index)=>({id:`MEDIA-${Date.now()}-${index}`,name:file.name,url:URL.createObjectURL(file),temporary:true}))];onResult(updateProfileDraft({media},operationId("media-add")))};const move=(index:number,dir:number)=>{const media=[...profile.draft.media],target=index+dir;if(target<0||target>=media.length)return;[media[index],media[target]]=[media[target],media[index]];onResult(updateProfileDraft({media},operationId("media-move")))};return <><input ref={input} className="sr-only" type="file" accept="image/*" multiple onChange={e=>add(e.target.files)}/><StateBlock title="Archivos locales temporales" body="Las vistas usan Object URL. Una recarga repone fixtures; no se presenta como subida remota."/><button className="more-media-add" onClick={()=>input.current?.click()}>+ Añadir fotos reales</button><div className="more-media-grid">{profile.draft.media.map((m,index)=><div className="more-media-tile" key={m.id}>{m.url?<img src={m.url} alt={m.name}/>:<BookOpen/>}<strong>{m.name}</strong><small>{m.temporary?"Temporal":"Guardada"}</small><div><button aria-label={`Mover ${m.name} arriba`} onClick={()=>move(index,-1)}>↑</button><button aria-label={`Mover ${m.name} abajo`} onClick={()=>move(index,1)}>↓</button></div></div>)}</div></>}
function PublicPreview({profile}:{profile:ReturnType<typeof moreStore.getSnapshot>["profile"]}){const[mode,setMode]=useState<"draft"|"published">("draft");const value=mode==="draft"?profile.draft:profile.published;return <><div className="more-segment"><button className={mode==="draft"?"is-active":""} onClick={()=>setMode("draft")}>Borrador</button><button className={mode==="published"?"is-active":""} onClick={()=>setMode("published")}>Publicado demo</button></div><article className="more-public-preview"><span>{mode==="draft"?`BORRADOR v${profile.draftVersion}`:`PUBLICADO DEMO v${profile.publishedVersion}`}</span><h1>{value.name}</h1><p>{value.description}</p><DataLine label="Contacto" value={value.phone||"Sin publicar"}/><DataLine label="Ubicación" value={value.address||"Sin publicar"}/><h2>Servicios disponibles</h2>{serviceRows().filter(({meta})=>meta.publicVisible).map(({service})=><MoreRow key={service.id} title={service.nombre} detail={`${service.duracionMin} min`} value={moneyArs(service.precio)}/>)}</article></>}
function PromotionEditor({onResult,onTargets,onConditions}:{onResult:(r:MoreResult)=>void;onTargets:()=>void;onConditions:()=>void}){const read=(key:string)=>sessionStorage.getItem(`p5-promo-${key}`)??"";const[name,setNameState]=useState(()=>read("name"));const[text,setTextState]=useState(()=>read("text"));const[benefit,setBenefitState]=useState(()=>read("benefit"));const setName=(value:string)=>{setNameState(value);sessionStorage.setItem("p5-promo-name",value)};const setText=(value:string)=>{setTextState(value);sessionStorage.setItem("p5-promo-text",value)};const setBenefit=(value:string)=>{setBenefitState(value);sessionStorage.setItem("p5-promo-benefit",value)};const targets=(()=>{try{return JSON.parse(sessionStorage.getItem("p5-promo-targets")??'["SV01"]') as string[]}catch{return ["SV01"]}})();const startsAt=read("start")||"2026-11-01",endsAt=read("end")||"2026-11-30";return <div className="more-form"><InputField id="p5-promo-name" label="Nombre interno" value={name} onChange={setName}/><InputField id="p5-promo-public" label="Texto público" value={text} onChange={setText}/><InputField id="p5-promo-benefit" label="Beneficio definido" value={benefit} onChange={setBenefit}/><SecondaryAction label={`Elegir objetivos · ${targets.length}`} onPress={onTargets} fullWidth/><SecondaryAction label="Vigencia y condiciones" onPress={onConditions} fullWidth/><StateBlock tone="warning" title="Activación condicionada" body="El borrador puede guardarse. La promoción no se activa sin política comercial."/><PrimaryAction label="Guardar promoción borrador" onPress={()=>{const result=savePromotion({name,publicText:text,targetIds:targets,benefit:benefit||"Sin definir",startsAt,endsAt,policyApproved:false},operationId("promo-create"));if(result.ok){["name","text","benefit","targets","start","end"].forEach(key=>sessionStorage.removeItem(`p5-promo-${key}`))}onResult(result)}} disabled={!name.trim()||!text.trim()||!targets.length} fullWidth/></div>}
function PromotionTargets(){const read=()=>{try{return new Set(JSON.parse(sessionStorage.getItem("p5-promo-targets")??'["SV01"]') as string[])}catch{return new Set<string>()}};const[selected,setSelected]=useState(read);const toggle=(id:string)=>setSelected(current=>{const next=new Set(current);next.has(id)?next.delete(id):next.add(id);sessionStorage.setItem("p5-promo-targets",JSON.stringify([...next]));return next});return <><StateBlock title="Objetos canónicos" body="Sólo servicios P2 y artículos públicos P3 pueden seleccionarse."/><Section title="Servicios">{serviceRows().map(({service:s,meta:m})=><label key={s.id} className="more-check-row"><span><strong>{s.nombre}</strong><small>{m.publicVisible?"Público":"Oculto"}</small></span><input type="checkbox" checked={selected.has(s.id)} onChange={()=>toggle(s.id)} disabled={!m.publicVisible}/></label>)}</Section><Section title="Productos">{p3PublicProducts().map(a=><label key={a.id} className="more-check-row"><span><strong>{a.name}</strong><small>{a.active?"Activo":"Inactivo"}</small></span><input type="checkbox" checked={selected.has(a.id)} onChange={()=>toggle(a.id)} disabled={!a.active}/></label>)}</Section></>}
function PromotionConditions({promo}:{promo?:ReturnType<typeof moreStore.getSnapshot>["promotions"][number]}){const[start,setStartState]=useState(()=>sessionStorage.getItem("p5-promo-start")??promo?.startsAt??"2026-11-01");const[end,setEndState]=useState(()=>sessionStorage.getItem("p5-promo-end")??promo?.endsAt??"2026-11-30");const setStart=(value:string)=>{setStartState(value);sessionStorage.setItem("p5-promo-start",value)};const setEnd=(value:string)=>{setEndState(value);sessionStorage.setItem("p5-promo-end",value)};return <div className="more-form"><InputField id="p5-promo-start" label="Inicio" type="date" value={start} onChange={setStart}/><InputField id="p5-promo-end" label="Fin" type="date" value={end} onChange={setEnd} error={start>end?"El fin debe ser posterior al inicio":undefined}/><SelectField id="p5-promo-stack" label="Acumulación" value="policy" onChange={()=>{}} options={[{id:"policy",label:"POLICY_REQUIRED"}]}/><StateBlock tone="warning" title="Regla pendiente" body="No se inventan límites de uso ni acumulación."/></div>}

function ScheduleSurface(p:ContentProps){
  const day="Lunes",intervals=p.state.schedule[day],impacts=scheduleImpacts(day,[])
  if(p.surface==="M55")return <><Section title="Disponibilidad"><MoreRow title="Horario local semanal" detail="Separado del calendario de cada profesional" onClick={()=>p.navigate("M56")}/><MoreRow title="Feriados y excepciones" detail={`${p.state.exceptions.length} excepciones`} onClick={()=>p.navigate("M57")}/><MoreRow title="Vista previa de disponibilidad" detail="Intersección Agenda, cursos y recursos" onClick={()=>p.navigate("M61")}/></Section><Section title="Reglas"><MoreRow title="Reglas generales de reserva" detail={p.state.bookingRules.enabled?"Reservas habilitadas":"Deshabilitadas"} onClick={()=>p.navigate("M58")}/><MoreRow title="Cancelación, ausencia y seña" detail={p.state.bookingRules.cancellationPolicyDefined?"Definida":"POLICY_REQUIRED"} onClick={()=>p.navigate("M59")}/><MoreRow title="Ventana de anticipación" detail={`${p.state.bookingRules.minNoticeMinutes/60} h · ${p.state.bookingRules.maxHorizonDays} días`} onClick={()=>p.navigate("M60")}/><MoreRow title="Recordatorios" detail={p.state.bookingRules.reminderEnabled?"Regla demo activa":"Deshabilitados"} onClick={()=>p.navigate("M64")}/><MoreRow title="Historial" detail="Antes, después y actor" onClick={()=>p.navigate("M65")}/></Section></>
  if(p.surface==="M56")return <WeekSchedule state={p.state.schedule} version={p.state.scheduleVersion} onResult={p.act} onImpact={()=>p.navigate("M63")}/>
  if(p.surface==="M57")return <ExceptionEditor onResult={p.act} onImpact={()=>p.navigate("M63")}/>
  if(p.surface==="M58")return <BookingRulesEditor state={p.state.bookingRules} onResult={p.act}/>
  if(p.surface==="M59")return <><StateBlock tone="warning" title="POLICY_REQUIRED" body="La retención de señas, cancelación y no-show no están aprobados. No se ejecuta dinero desde aquí."/><DataLine label="Configuración actual" value="Sin política activa"/><SecondaryAction label="Consultar señas en Finanzas" onPress={()=>p.handoff("finanzas","financeSurface=F32")} fullWidth/></>
  if(p.surface==="M60")return <AdvanceWindow state={p.state.bookingRules} onResult={p.act} onPreview={()=>p.navigate("M61")}/>
  if(p.surface==="M61")return <AvailabilityPreview onOrigin={()=>p.handoff("equipo","agendaAction=new")}/>
  if(p.surface==="M62")return <><StateBlock tone="warning" title="Conflictos por recurso" body="Los intervalos usan [inicio, fin). Se bloquea sólo el instructor o recurso ocupado."/><Section title="Choques detectados">{sessionConflicts("2026-10-26T10:00:00-03:00","2026-10-26T11:30:00-03:00","ST01").map(c=><MoreRow key={c.id} title={`${c.type} · ${c.id}`} detail={c.label} status="Requiere alternativa" onClick={()=>c.type.includes("Reserva")?p.handoff("equipo",`agendaReservation=${c.id}`):p.navigate("M30")}/>)}</Section></>
  if(p.surface==="M63")return <><div className="more-compare"><DataLine label="Antes" value="Lunes 09:00–20:00"/><DataLine label="Después" value="Cierre propuesto"/></div><Section title="Objetos afectados">{impacts.length?impacts.map(i=><MoreRow key={i.id} title={`${i.type} · ${i.id}`} detail="Debe resolverse en su dominio" status="Pendiente" onClick={()=>i.type.includes("Reserva")?p.handoff("equipo",`agendaReservation=${i.id}`):p.navigate("M30")}/>):<MoreRow title="Sin impactos" detail="La revisión se recalcula al confirmar."/>}</Section><StateBlock tone="warning" title="Confirmación coordinada" body="No existe Cancelar todo. Cada objeto conserva su dueño e identidad."/></>
  if(p.surface==="M64")return <ReminderEditor state={p.state.bookingRules} onResult={p.act}/>
  return <><Section title="Cambios auditados">{allAuditEvents().filter(e=>e.domain==="Horarios").map(e=><MoreRow key={e.id} title={e.action} detail={`${e.actor} · ${e.at.slice(0,16).replace("T"," ")}`}/>)}</Section></>
}

function WeekSchedule({state,version,onResult,onImpact}:{state:ReturnType<typeof moreStore.getSnapshot>["schedule"];version:number;onResult:(r:MoreResult)=>void;onImpact:()=>void}){const[days,setDays]=useState(()=>structuredClone(state));const save=()=>{if(Object.entries(days).some(([day,bands])=>scheduleImpacts(day,bands).length)){onImpact();return}onResult(updateWeekSchedule(days,version,operationId("schedule-week")))};return <>{Object.entries(days).map(([day,bands])=><div className="more-day" key={day}><div><strong>{day}</strong><small>{bands.length?`${bands.length} franja(s)`:"Cerrado"}</small></div>{bands.map((b,index)=><div className="more-interval" key={b.id}><input aria-label={`${day} inicio ${index+1}`} type="time" value={b.start} onChange={e=>setDays(c=>({...c,[day]:c[day].map(x=>x.id===b.id?{...x,start:e.target.value}:x)}))}/><span>—</span><input aria-label={`${day} fin ${index+1}`} type="time" value={b.end} onChange={e=>setDays(c=>({...c,[day]:c[day].map(x=>x.id===b.id?{...x,end:e.target.value}:x)}))}/></div>)}</div>)}<PrimaryAction label="Revisar horario semanal" onPress={save} fullWidth/></>}
function ExceptionEditor({onResult,onImpact}:{onResult:(r:MoreResult)=>void;onImpact:()=>void}){const[date,setDate]=useState("2026-10-26");const[type,setType]=useState("closed");const[reason,setReason]=useState("");return <div className="more-form"><InputField id="p5-exception-date" label="Fecha" type="date" value={date} onChange={setDate}/><SelectField id="p5-exception-type" label="Tipo" value={type} onChange={setType} options={[{id:"closed",label:"Cierre completo"},{id:"special",label:"Horario especial"}]}/><InputField id="p5-exception-reason" label="Motivo" value={reason} onChange={setReason}/><PrimaryAction label="Revisar excepción" onPress={()=>{if(todasLasReservas().some(r=>r.inicio.startsWith(date)&&r.estado==="confirmada")){onImpact();return}onResult(addScheduleException({id:`EXC-${date}`,date,type:type as "closed"|"special",intervals:[],reason},operationId("schedule-exception")))}} fullWidth/></div>}
function BookingRulesEditor({state,onResult}:{state:ReturnType<typeof moreStore.getSnapshot>["bookingRules"];onResult:(r:MoreResult)=>void}){const[enabled,setEnabled]=useState(state.enabled);return <><label className="more-switch"><span><strong>Reservas públicas</strong><small>Requieren servicio y profesional elegibles.</small></span><input type="checkbox" checked={enabled} onChange={e=>setEnabled(e.target.checked)}/></label><StateBlock title="Buffers no inferidos" body="No se agregan tiempos entre reservas sin política explícita."/><PrimaryAction label="Guardar regla" onPress={()=>onResult(updateBookingRules({enabled},operationId("booking-rules")))} fullWidth/></>}
function AdvanceWindow({state,onResult,onPreview}:{state:ReturnType<typeof moreStore.getSnapshot>["bookingRules"];onResult:(r:MoreResult)=>void;onPreview:()=>void}){const[min,setMin]=useState(String(state.minNoticeMinutes/60));const[max,setMax]=useState(String(state.maxHorizonDays));return <div className="more-form"><InputField id="p5-notice-min" label="Anticipación mínima · horas" type="number" value={min} onChange={setMin}/><InputField id="p5-horizon-max" label="Horizonte máximo · días" type="number" value={max} onChange={setMax}/><SecondaryAction label="Ver disponibilidad resultante" onPress={onPreview} fullWidth/><PrimaryAction label="Guardar ventana" onPress={()=>onResult(updateBookingRules({minNoticeMinutes:Number(min)*60,maxHorizonDays:Number(max)},operationId("booking-window")))} disabled={Number(min)<0||Number(max)<1} fullWidth/></div>}
function AvailabilityPreview({onOrigin}:{onOrigin:()=>void}){const[date,setDate]=useState("2026-10-26");const[serviceId,setServiceId]=useState("SV01");const[staffId,setStaffId]=useState("ST01");const conflicts=sessionConflicts(`${date}T10:00:00-03:00`,`${date}T10:30:00-03:00`,staffId);return <div className="more-form"><InputField id="p5-preview-date" label="Fecha" type="date" value={date} onChange={setDate}/><SelectField id="p5-preview-service" label="Servicio" value={serviceId} onChange={setServiceId} options={SERVICIOS.map(s=>({id:s.id,label:s.nombre}))}/><SelectField id="p5-preview-staff" label="Profesional" value={staffId} onChange={setStaffId} options={PROFESIONALES.filter(i=>i.estado==="activo").map(i=>({id:i.id,label:i.nombre}))}/>{conflicts.length?<StateBlock tone="warning" title="Sin slot a las 10:00" body={`${conflicts[0].type} ${conflicts[0].id} ocupa la franja.`}/>:<div className="more-slot-grid"><button>09:00</button><button>10:00</button><button>11:30</button></div>}<SecondaryAction label="Abrir origen en Agenda" onPress={onOrigin} fullWidth/></div>}
function ReminderEditor({state,onResult}:{state:ReturnType<typeof moreStore.getSnapshot>["bookingRules"];onResult:(r:MoreResult)=>void}){const[enabled,setEnabled]=useState(state.reminderEnabled);const[lead,setLead]=useState(String(state.reminderLeadHours));return <div className="more-form"><label className="more-switch"><span><strong>Regla demo activa</strong><small>No implica entrega externa.</small></span><input type="checkbox" checked={enabled} onChange={e=>setEnabled(e.target.checked)}/></label><InputField id="p5-reminder-lead" label="Anticipación · horas" type="number" value={lead} onChange={setLead}/><StateBlock title="Canal no conectado" body="No se enviarán mensajes de WhatsApp, SMS ni correo."/><PrimaryAction label="Guardar configuración demo" onPress={()=>onResult(updateBookingRules({reminderEnabled:enabled,reminderLeadHours:Number(lead)},operationId("reminder-rule")))} fullWidth/></div>}

function SettingsSurface(p:ContentProps){
  const account=p.state.accounts.find(item=>item.id===p.accountId)??p.state.accounts[0]
  if(p.surface==="M66")return <><Section title="Negocio"><MoreRow title="Datos internos" detail={p.state.business.internalName} onClick={()=>p.navigate("M67")}/><MoreRow title="Preferencias operativas" detail="Formato y comportamiento local" onClick={()=>p.navigate("M74")}/></Section><Section title="Acceso demo"><MoreRow title="Cuentas" detail={`${p.state.accounts.filter(item=>item.status==="active").length} activas`} onClick={()=>p.navigate("M68")}/><MoreRow title="Seguridad y límites" detail="Sin autenticación productiva" onClick={()=>p.navigate("M75")}/></Section></>
  if(p.surface==="M67")return <BusinessEditor state={p.state.business} onResult={p.act}/>
  if(p.surface==="M68")return <><StateBlock title="AccountID separado de StaffID" body="Una cuenta demo puede vincularse a un integrante, pero sus identidades no se fusionan."/><Section title="Cuentas demo">{p.state.accounts.map(item=><MoreRow key={item.id} icon={<UserRound size={19}/>} title={item.label} detail={`${item.email} · ${item.staffId??"sin StaffID"}`} status={item.status} onClick={()=>p.navigate("M69",{accountId:item.id})}/>)}</Section></>
  if(p.surface==="M69")return <><Hero title={account.label} subtitle={account.email} status={`${account.status} · ${account.role}`}/><Section title="Identidades"><MoreRow title="AccountID" value={account.id}/><MoreRow title="StaffID" value={account.staffId??"Sin vínculo"} onClick={()=>p.navigate("M70")}/></Section><Section title="Acceso"><MoreRow title="Capacidades" detail={`${Object.values(account.capabilities).filter(Boolean).length} habilitadas`} onClick={()=>p.navigate("M71")}/><MoreRow title="Revisar permisos" detail="Comparar cambios antes de guardar" onClick={()=>p.navigate("M72")}/><MoreRow title={account.status==="suspended"?"Reactivar cuenta":"Suspender cuenta"} detail="El integrante y la historia permanecen" onClick={()=>p.navigate("M73")}/></Section></>
  if(p.surface==="M70")return <AccountLinker account={account} onResult={p.act}/>
  if(p.surface==="M71")return <CapabilitiesEditor account={account} onReview={()=>p.navigate("M72")}/>
  if(p.surface==="M72")return <PermissionReview account={account} onResult={p.act}/>
  if(p.surface==="M73")return <><Hero title={account.label} subtitle={account.staffId?`Vinculada a ${account.staffId}`:"Sin integrante vinculado"} status={account.status}/><StateBlock tone="warning" title="Acceso separado del integrante" body="Suspender una cuenta demo no desactiva al profesional, no cancela reservas y no borra auditoría."/><PrimaryAction label={account.status==="suspended"?"Reactivar cuenta demo":"Suspender cuenta demo"} onPress={()=>p.act(setAccountStatus(account.id,account.status==="suspended"?"active":"suspended",account.version,operationId("account-status")))} fullWidth/></>
  if(p.surface==="M74")return <OperationalPreferences onResult={p.act}/>
  return <><StateBlock tone="warning" title="Prototipo sin autenticación productiva" body="No hay contraseñas, sesiones remotas, MFA, invitaciones ni correos reales. Esos controles requieren backend e identidad aprobada."/><Section title="Límites explícitos"><MoreRow title="Sesión local" detail="Se reinicia con los fixtures del prototipo" status="DEMO"/><MoreRow title="Recuperación de acceso" detail="Sin proveedor conectado" status="POLICY_REQUIRED"/><MoreRow title="Registro de acciones" detail="Auditoría funcional local" onClick={()=>p.navigate("M76")}/></Section></>
}

function BusinessEditor({state,onResult}:{state:ReturnType<typeof moreStore.getSnapshot>["business"];onResult:(r:MoreResult)=>void}){
  const[name,setName]=useState(state.internalName);const[phone,setPhone]=useState(state.adminPhone);const[address,setAddress]=useState(state.address);const[timezone,setTimezone]=useState(state.timezone)
  return <div className="more-form"><InputField id="p5-business-name" label="Nombre interno" value={name} onChange={setName}/><InputField id="p5-business-phone" label="Teléfono administrativo" value={phone} onChange={setPhone}/><InputField id="p5-business-address" label="Dirección interna" value={address} onChange={setAddress}/><SelectField id="p5-business-timezone" label="Zona horaria" value={timezone} onChange={setTimezone} options={[{id:"America/Argentina/Buenos_Aires",label:"Buenos Aires (UTC−3)"},{id:"America/Montevideo",label:"Montevideo (UTC−3)"}]}/><StateBlock title="Datos internos" body="Estos campos no cambian el perfil público ni publican información externa."/><PrimaryAction label="Guardar datos internos" onPress={()=>onResult(updateBusiness({internalName:name,adminPhone:phone,address,timezone},state.version,operationId("business-update")))} disabled={!name.trim()} fullWidth/></div>
}

function AccountLinker({account,onResult}:{account:ReturnType<typeof moreStore.getSnapshot>["accounts"][number];onResult:(r:MoreResult)=>void}){
  const[staffId,setStaffId]=useState(account.staffId??"");const staff=listStaff()
  return <div className="more-form"><DataLine label="Cuenta demo" value={`${account.label} · ${account.id}`}/><SelectField id="p5-account-staff" label="Integrante" value={staffId} onChange={setStaffId} options={[{id:"",label:"Elegí un integrante"},...staff.map(item=>({id:item.id,label:`${item.name} · ${item.id}`}))]}/>{staffId?<StateBlock title="Vínculo de identidades" body={`AccountID ${account.id} seguirá siendo distinto de StaffID ${staffId}.`}/>:null}<PrimaryAction label="Vincular cuenta demo" onPress={()=>onResult(linkDemoAccount(account.id,staffId,operationId("account-link")))} disabled={!staffId} fullWidth/></div>
}

const CAPABILITY_LABELS:Record<string,string>={"agenda.view":"Ver Agenda","agenda.edit":"Editar Agenda","clients.view":"Ver Clientes","clients.edit":"Editar Clientes","services.edit":"Editar Servicios","courses.edit":"Editar Cursos","inventory.view":"Ver Inventario","finance.view":"Ver Finanzas","settings.admin":"Administrar configuración","audit.view":"Ver auditoría"}
function CapabilitiesEditor({account,onReview}:{account:ReturnType<typeof moreStore.getSnapshot>["accounts"][number];onReview:()=>void}){const[values,setValues]=useState(account.capabilities);return <><StateBlock title="Capacidades explícitas" body="No se infieren permisos por etiqueta de rol; se guarda el conjunto revisado."/><Section title="Capacidades">{Object.entries(values).map(([key,value])=><label key={key} className="more-check-row"><span><strong>{CAPABILITY_LABELS[key]??key}</strong><small>{key}</small></span><input type="checkbox" checked={value} onChange={e=>setValues(current=>({...current,[key]:e.target.checked}))}/></label>)}</Section><PrimaryAction label="Revisar permisos" onPress={()=>{sessionStorage.setItem(`p5-capabilities-${account.id}`,JSON.stringify(values));onReview()}} fullWidth/></>}
function PermissionReview({account,onResult}:{account:ReturnType<typeof moreStore.getSnapshot>["accounts"][number];onResult:(r:MoreResult)=>void}){let proposed=account.capabilities;try{proposed=JSON.parse(sessionStorage.getItem(`p5-capabilities-${account.id}`)??JSON.stringify(account.capabilities))}catch{/* conserva estado actual */}const changed=Object.keys(proposed).filter(key=>proposed[key]!==account.capabilities[key]);return <><Hero title={account.label} subtitle="Revisión atómica de capacidades" status={`${changed.length} cambio(s)`}/><Section title="Diferencias">{changed.length?changed.map(key=><MoreRow key={key} title={CAPABILITY_LABELS[key]??key} detail={account.capabilities[key]?"Habilitado → Deshabilitado":"Deshabilitado → Habilitado"}/>):<MoreRow title="Sin diferencias" detail="Volvé a Capacidades para modificar el conjunto."/>}</Section>{account.capabilities["settings.admin"]&&!proposed["settings.admin"]?<StateBlock tone="warning" title="Continuidad administrativa" body="La operación se bloqueará si esta es la última cuenta administradora activa."/>:null}<PrimaryAction label="Confirmar permisos" onPress={()=>onResult(updateCapabilities(account.id,proposed,account.version,operationId("capabilities-update")))} disabled={!changed.length} fullWidth/></>}
function OperationalPreferences({onResult}:{onResult:(r:MoreResult)=>void}){const[weekStart,setWeekStart]=useState("monday");const[compact,setCompact]=useState(false);return <div className="more-form"><SelectField id="p5-week-start" label="Inicio de semana" value={weekStart} onChange={setWeekStart} options={[{id:"monday",label:"Lunes"},{id:"sunday",label:"Domingo"}]}/><label className="more-switch"><span><strong>Densidad compacta</strong><small>Afecta sólo listas operativas locales.</small></span><input type="checkbox" checked={compact} onChange={e=>setCompact(e.target.checked)}/></label><StateBlock title="Preferencia local" body="No cambia moneda, impuestos, políticas comerciales ni registros históricos."/><PrimaryAction label="Guardar preferencia demo" onPress={()=>onResult({ok:true,status:"confirmed",message:`Preferencias locales guardadas: ${weekStart}, ${compact?"compacta":"cómoda"}`,operationId:operationId("preferences")})} fullWidth/></div>}

function ActivitySurface(p:ContentProps){
  const events=allAuditEvents();const selectedAlert=p.state.alerts.find(item=>item.id===p.alertId)??p.state.alerts[0];const selectedEvent=events[0]
  if(p.surface==="M76")return <><Toolbar search="" setSearch={()=>{}} onFilter={()=>p.navigate("M78")}/><Section title="Actividad reciente">{events.slice(0,12).map(event=><MoreRow key={event.id} icon={<History size={18}/>} title={event.action} detail={`${event.domain} · ${event.actor}`} status={event.at.slice(0,10)} onClick={()=>p.navigate("M77")}/>)}</Section><button className="more-inline-link" onClick={()=>p.navigate("M79")}>Ver avisos operativos</button></>
  if(p.surface==="M77")return selectedEvent?<><Hero title={selectedEvent.action} subtitle={`${selectedEvent.actor} · ${selectedEvent.at.replace("T"," ").slice(0,19)}`} status={selectedEvent.domain}/><Section title="Trazabilidad"><MoreRow title="Tipo de objeto" value={selectedEvent.objectType}/><MoreRow title="Identificador" value={selectedEvent.objectId}/>{selectedEvent.before?<MoreRow title="Antes" detail={selectedEvent.before}/>:null}{selectedEvent.after?<MoreRow title="Después" detail={selectedEvent.after}/>:null}</Section><StateBlock title="Evento inmutable" body="Las correcciones crean un nuevo evento relacionado; no reescriben este registro."/></>:<StateBlock title="Sin evento" body="No hay actividad disponible."/>
  if(p.surface==="M78")return <ActivitySearch events={events}/>
  if(p.surface==="M79")return <><Section title="Pendientes">{p.state.alerts.filter(item=>!item.resolved).map(item=><MoreRow key={item.id} icon={<Bell size={18}/>} title={item.title} detail={`${item.domain} · ${item.detail}`} status={item.read?"Leído":item.priority==="high"?"Prioridad alta":"Nuevo"} onClick={()=>{markAlertRead(item.id);p.navigate("M80",{alertId:item.id})}}/>)}</Section><SecondaryAction label="Preferencias de avisos" onPress={()=>p.navigate("M81")} fullWidth/></>
  if(p.surface==="M80")return selectedAlert?<><Hero title={selectedAlert.title} subtitle={selectedAlert.detail} status={`${selectedAlert.domain} · ${selectedAlert.priority}`}/><DataLine label="Objeto propietario" value={selectedAlert.objectId}/><StateBlock title="Aviso no es auditoría" body="Leer o resolver este aviso no modifica el evento histórico que explica su origen."/><PrimaryAction label={`Abrir ${selectedAlert.domain}`} onPress={()=>openAlertOwner(selectedAlert.domain,selectedAlert.objectId,p)} fullWidth/><SecondaryAction label="Recuperación y corrección" onPress={()=>p.navigate("M82")} fullWidth/></>:<StateBlock title="Aviso no disponible" body="Volvé al listado de avisos."/>
  if(p.surface==="M81")return <NotificationPreferences onResult={p.act}/>
  if(p.surface==="M82")return <><StateBlock tone="warning" title="Corrección compensatoria" body="No se elimina ni edita un evento histórico. La corrección debe ejecutarse en el dominio propietario y generar otro evento enlazado."/><Section title="Rutas de recuperación"><MoreRow title="Agenda" detail="Reprogramar o corregir atención" onClick={()=>p.handoff("equipo","agendaAction=review")}/><MoreRow title="Inventario" detail="Ajustar stock o pedido" onClick={()=>p.handoff("inventario","inventorySurface=I43")}/><MoreRow title="Finanzas" detail="Ajuste o reversión documentada" onClick={()=>p.handoff("finanzas","financeSurface=F61")}/></Section></>
  return <><StateBlock tone="warning" title="Incidencias cruzadas" body="Cada incidencia conserva el objeto fuente, el dominio propietario y la acción disponible. No hay un estado global inventado."/><Section title="Requieren coordinación">{p.state.alerts.filter(item=>item.priority==="high").map(item=><MoreRow key={item.id} title={item.title} detail={`${item.domain} · ${item.objectId}`} status={item.resolved?"Resuelta":"Abierta"} onClick={()=>p.navigate("M80",{alertId:item.id})}/>)}</Section><DataLine label="Invariantes P5" value={verifyMoreInvariants().length?`${verifyMoreInvariants().length} error(es)`:"Íntegras"}/></>
}

function ActivitySearch({events}:{events:ReturnType<typeof allAuditEvents>}){const[query,setQuery]=useState("");const[domain,setDomain]=useState("all");const filtered=events.filter(event=>(domain==="all"||event.domain===domain)&&`${event.action} ${event.actor} ${event.objectId}`.toLowerCase().includes(query.toLowerCase()));return <><Toolbar search={query} setSearch={setQuery}/><div className="more-form"><SelectField id="p5-activity-domain" label="Dominio" value={domain} onChange={setDomain} options={[{id:"all",label:"Todos"},...Array.from(new Set(events.map(event=>event.domain))).map(item=>({id:item,label:item}))]}/></div><Section title={`${filtered.length} resultado(s)`}>{filtered.map(event=><MoreRow key={event.id} title={event.action} detail={`${event.domain} · ${event.objectId}`} status={event.at.slice(0,10)}/>)}</Section></>}
function NotificationPreferences({onResult}:{onResult:(r:MoreResult)=>void}){const[inApp,setInApp]=useState(true);const[priority,setPriority]=useState(true);return <div className="more-form"><label className="more-switch"><span><strong>Avisos dentro de la app</strong><small>Centro compartido del Dueño.</small></span><input type="checkbox" checked={inApp} onChange={e=>setInApp(e.target.checked)}/></label><label className="more-switch"><span><strong>Prioridad alta destacada</strong><small>No implica una notificación push.</small></span><input type="checkbox" checked={priority} onChange={e=>setPriority(e.target.checked)}/></label><StateBlock title="Sin canales externos" body="Correo, SMS, WhatsApp y push no están conectados ni se simulan como entregados."/><PrimaryAction label="Guardar preferencias locales" onPress={()=>onResult({ok:true,status:"confirmed",message:`Centro local ${inApp?"activo":"silenciado"}; prioridad ${priority?"destacada":"normal"}`,operationId:operationId("alerts-preferences")})} fullWidth/></div>}
function openAlertOwner(domain:string,objectId:string,p:ContentProps){if(domain==="Inventario")p.handoff("inventario",`inventorySurface=I19&articleId=${objectId}`);else if(domain==="Finanzas")p.handoff("finanzas",`financeSurface=F68&financeOrigin=${objectId}`);else if(domain==="Agenda")p.handoff("equipo",`agendaReservation=${objectId}`);else if(domain==="Cursos")p.navigate("M27",{courseId:objectId});else p.navigate("M16",{serviceId:objectId})}

